macro_rules! from_ptr_range_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function from_ptr_range in module {}", module_path!());
    };
}

mkfn!{
    from_ptr_range_introspect!();
    # [doc = " Forms a slice from a pointer range."] # [doc = ""] # [doc = " This function is useful for interacting with foreign interfaces which"] # [doc = " use two pointers to refer to a range of elements in memory, as is"] # [doc = " common in C++."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Behavior is undefined if any of the following conditions are violated:"] # [doc = ""] # [doc = " * The `start` pointer of the range must be a non-null, [valid] and properly aligned pointer"] # [doc = "   to the first element of a slice."] # [doc = ""] # [doc = " * The `end` pointer must be a [valid] and properly aligned pointer to *one past*"] # [doc = "   the last element, such that the offset from the end to the start pointer is"] # [doc = "   the length of the slice."] # [doc = ""] # [doc = " * The entire memory range of this slice must be contained within a single allocation!"] # [doc = "   Slices can never span across multiple allocations."] # [doc = ""] # [doc = " * The range must contain `N` consecutive properly initialized values of type `T`."] # [doc = ""] # [doc = " * The memory referenced by the returned slice must not be mutated for the duration"] # [doc = "   of lifetime `'a`, except inside an `UnsafeCell`."] # [doc = ""] # [doc = " * The total length of the range must be no larger than `isize::MAX`,"] # [doc = "   and adding that size to `start` must not \"wrap around\" the address space."] # [doc = "   See the safety documentation of [`pointer::offset`]."] # [doc = ""] # [doc = " Note that a range created from [`slice::as_ptr_range`] fulfills these requirements."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function panics if `T` is a Zero-Sized Type (“ZST”)."] # [doc = ""] # [doc = " # Caveat"] # [doc = ""] # [doc = " The lifetime for the returned slice is inferred from its usage. To"] # [doc = " prevent accidental misuse, it's suggested to tie the lifetime to whichever"] # [doc = " source lifetime is safe in the context, such as by providing a helper"] # [doc = " function taking the lifetime of a host value for the slice, or by explicit"] # [doc = " annotation."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(slice_from_ptr_range)]"] # [doc = ""] # [doc = " use core::slice;"] # [doc = ""] # [doc = " let x = [1, 2, 3];"] # [doc = " let range = x.as_ptr_range();"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     assert_eq!(slice::from_ptr_range(range), &x);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [valid]: ptr#safety"] # [unstable (feature = "slice_from_ptr_range" , issue = "89792")] # [rustc_const_unstable (feature = "const_slice_from_ptr_range" , issue = "89792")] # [track_caller] pub const unsafe fn from_ptr_range < 'a , T > (range : Range < * const T >) -> & 'a [T] { unsafe { from_raw_parts (range . start , range . end . offset_from_unsigned (range . start)) } }
}

